def compress(s):
    if s == '':
        return ''
    out = ''
    cur = s[0]
    n = 1
    for ch in s[1:]:
        if ch == cur:
            n += 1
        else:
            out += cur + str(n)
            cur = ch
            n = 1
    return out + cur + str(n)
