def expand(s):
    out = ''
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num = ''
        while i < len(s) and '0' <= s[i] <= '9':
            num += s[i]
            i += 1
        out += ch * int(num)
    return out
